var t={id:"ch8",title:"\u0627\u0644\u0635\u064A\u0627\u0646\u0629 \u0627\u0644\u0648\u0642\u0627\u0626\u064A\u0629 \u0648\u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F \u0641\u064A \u0627\u0644\u0637\u0627\u0642\u0629",icon:"fa-wrench",sections:[{id:"ch8-sec1",title:"1. \u0627\u0644\u0639\u062C\u0644\u0627\u062A \u0627\u0644\u0645\u0637\u0627\u0637\u064A\u0629 \u0648\u0636\u063A\u0637 \u0627\u0644\u0647\u0648\u0627\u0621",icon:"fa-car-side",type:"general",items:[{id:"ch8-r1",title:"\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0623\u0637\u0648\u0627\u0642 \u062D\u0633\u0628 \u0627\u0644\u062C\u0648\u062F\u0629",description:"\u062A\u062E\u062A\u0644\u0641 \u062C\u0648\u062F\u0629 \u0627\u0644\u0625\u0637\u0627\u0631\u0627\u062A \u0628\u0627\u062E\u062A\u0644\u0627\u0641 \u0637\u0631\u064A\u0642\u0629 \u0635\u0646\u0639 \u0647\u064A\u0643\u0644\u0647\u0627 \u0627\u0644\u062F\u0627\u062E\u0644\u064A:",list:["1. \u0634\u0639\u0627\u0639\u064A (Radial): \u0623\u0641\u0636\u0644 \u062C\u0648\u062F\u0629 \u0639\u0644\u0649 \u0627\u0644\u0625\u0637\u0644\u0627\u0642 (\u0645\u0645\u062A\u0627\u0632).","2. \u0645\u0637\u0648\u0642 (Bias-Belted): \u062C\u0648\u062F\u0629 \u0645\u062A\u0648\u0633\u0637\u0629 (\u062C\u064A\u062F).","3. \u0642\u0637\u0631\u064A \u0639\u0627\u062F\u064A (Diagonal): \u0623\u0642\u0644 \u062C\u0648\u062F\u0629 (\u0642\u062F\u064A\u0645)."],imageOrSvg:'<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><circle cx="50" cy="50" r="40" fill="none" stroke="#475569" stroke-width="10"/><circle cx="50" cy="50" r="25" fill="none" stroke="#94a3b8" stroke-width="5" stroke-dasharray="4,2"/><path d="M 50 10 L 50 90 M 10 50 L 90 50" stroke="#94a3b8" stroke-width="2"/></svg>',alertType:"success"},{id:"ch8-r2",title:"\u0642\u0627\u0639\u062F\u0629 \u062A\u0631\u0643\u064A\u0628 \u0627\u0644\u0623\u0637\u0648\u0627\u0642 (\u0627\u0644\u0647\u0627\u0645\u0629 \u062C\u062F\u0627\u064B)",description:"\u0644\u0636\u0645\u0627\u0646 \u062A\u0648\u0627\u0632\u0646 \u0627\u0644\u0639\u0631\u0628\u0629\u060C \u064A\u062C\u0628 \u0627\u062A\u0628\u0627\u0639 \u0627\u0644\u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0635\u0627\u0631\u0645\u0629 \u0627\u0644\u062A\u0627\u0644\u064A\u0629:",list:["\u0639\u0646\u062F \u062A\u0631\u0643\u064A\u0628 \u0646\u0648\u0639 \u0639\u0644\u0649 \u0627\u0644\u0645\u063A\u0632\u0644 \u0627\u0644\u0623\u0645\u0627\u0645\u064A\u060C \u064A\u062C\u0628 \u062A\u0631\u0643\u064A\u0628 \u0646\u0648\u0639 \u0645\u062B\u0644\u0647 \u0623\u0648 \u0623\u062D\u0633\u0646 \u0645\u0646\u0647 \u0639\u0644\u0649 \u0627\u0644\u0645\u063A\u0632\u0644 \u0627\u0644\u062E\u0644\u0641\u064A.","\u064A\u064F\u0645\u0646\u0639 \u062A\u0631\u0643\u064A\u0628 \u0647\u064A\u0627\u0643\u0644 \u0645\u062E\u062A\u0644\u0641\u0629 \u0639\u0644\u0649 \u0646\u0641\u0633 \u0627\u0644\u0645\u063A\u0632\u0644 \u062A\u0645\u0627\u0645\u0627\u064B.","\u0627\u0644\u0627\u0633\u062A\u062B\u0646\u0627\u0621 \u0627\u0644\u0648\u062D\u064A\u062F: \u064A\u0633\u0645\u062D \u0628\u062A\u0631\u0643\u064A\u0628 \u0639\u062C\u0644\u0627\u062A \u0645\u062E\u062A\u0644\u0641\u0629 \u0641\u0642\u0637 \u0639\u0646\u062F \u0625\u0646\u0641\u0644\u0627\u0642 \u0639\u062C\u0644\u0629 \u0641\u062C\u0623\u0629 \u0628\u0627\u0644\u0637\u0631\u064A\u0642 \u0644\u0644\u0648\u0635\u0648\u0644 \u0644\u0623\u0642\u0631\u0628 \u0648\u0631\u0634\u0629."],imageOrSvg:'<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><rect x="20" y="10" width="15" height="25" fill="#475569"/><rect x="65" y="10" width="15" height="25" fill="#475569"/><rect x="20" y="65" width="15" height="25" fill="#0284c7"/><rect x="65" y="65" width="15" height="25" fill="#0284c7"/><path d="M 27 35 L 27 65 M 72 35 L 72 65" stroke="#94a3b8" stroke-width="2" stroke-dasharray="4,4"/></svg>',alertType:"danger"},{id:"ch8-r3",title:"\u0645\u0642\u0627\u064A\u064A\u0633 \u062A\u0622\u0643\u0644 \u0627\u0644\u0639\u062C\u0644\u0627\u062A",description:"\u0627\u0644\u0645\u0642\u0627\u064A\u064A\u0633 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A\u0629 \u0648\u0627\u0644\u062A\u0642\u0646\u064A\u0629 \u0644\u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u0625\u0637\u0627\u0631\u0627\u062A:",list:["1 \u0645\u0645: \u0627\u0644\u0639\u0645\u0642 \u0627\u0644\u0623\u062F\u0646\u0649 \u0644\u0644\u0623\u062E\u0627\u062F\u064A\u062F \u0627\u0644\u0623\u0633\u0627\u0633\u064A\u0629.","1.6 \u0645\u0645: \u0645\u0624\u0634\u0631 \u0627\u0644\u062A\u0647\u0631\u0626\u0629 (\u064A\u0639\u0644\u0646 \u0636\u0631\u0648\u0631\u0629 \u0627\u0644\u062A\u063A\u064A\u064A\u0631 \u0641\u0648\u0631\u0627\u064B).","5 \u0645\u0645: \u0623\u0642\u0635\u0649 \u0641\u0627\u0631\u0642 \u0645\u0633\u0645\u0648\u062D \u0628\u0647 \u0628\u064A\u0646 \u062A\u0622\u0643\u0644 \u0639\u062C\u0644\u062A\u064A \u0646\u0641\u0633 \u0627\u0644\u0645\u063A\u0632\u0644."],imageOrSvg:'<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><rect x="40" y="20" width="20" height="60" fill="#e2e8f0"/><rect x="40" y="20" width="20" height="5" fill="#ef4444"/><rect x="40" y="75" width="20" height="5" fill="#22c55e"/><path d="M 40 40 L 60 40" stroke="#475569" stroke-width="2"/><text x="70" y="42" font-size="10" fill="#475569">1.6mm</text></svg>',alertType:"danger"},{id:"ch8-r4",title:"\u0645\u062E\u0627\u0637\u0631 \u0636\u063A\u0637 \u0627\u0644\u0647\u0648\u0627\u0621 \u0627\u0644\u062E\u0627\u0637\u0626",description:"\u062A\u0623\u062B\u064A\u0631 \u0636\u063A\u0637 \u0627\u0644\u0647\u0648\u0627\u0621 \u0639\u0644\u0649 \u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u0633\u064A\u0631:",list:["\u0627\u0644\u0646\u0641\u062E \u0623\u0643\u062B\u0631 \u0645\u0646 \u0627\u0644\u0644\u0627\u0632\u0645: \u064A\u0633\u0628\u0628 \u0627\u0646\u0632\u0644\u0627\u0642 \u0627\u0644\u0639\u0631\u0628\u0629 \u0648\u062A\u062E\u0641\u064A\u0636 \u0627\u0644\u062A\u062D\u0627\u0645 \u0627\u0644\u0623\u0637\u0648\u0627\u0642 \u0628\u0627\u0644\u0645\u0639\u0628\u062F.","\u0627\u0644\u0646\u0641\u062E \u0623\u0642\u0644 \u0645\u0646 \u0627\u0644\u0644\u0627\u0632\u0645: \u064A\u0633\u0628\u0628 \u062E\u0637\u0631 \u0627\u0646\u0641\u0644\u0627\u0642 \u0627\u0644\u0639\u062C\u0644\u0629 \u0648\u0632\u064A\u0627\u062F\u0629 \u0645\u0641\u0631\u0637\u0629 \u0641\u064A \u062D\u0631\u0627\u0631\u062A\u0647\u0627."],imageOrSvg:'<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><circle cx="50" cy="50" r="40" fill="none" stroke="#ef4444" stroke-width="8"/><path d="M 50 20 L 50 80 M 20 50 L 80 50" stroke="#ef4444" stroke-width="4"/><path d="M 35 35 L 65 65 M 65 35 L 35 65" stroke="#ef4444" stroke-width="4"/></svg>'},{id:"ch8-r5",title:"\u0627\u0644\u0636\u063A\u0637 \u0639\u0646\u062F \u0627\u0644\u0633\u0641\u0631 \u0648\u0627\u0644\u062D\u0645\u0648\u0644\u0629",description:"\u064A\u062C\u0628 \u0625\u0636\u0627\u0641\u0629 \u0636\u063A\u0637 \u0625\u0636\u0627\u0641\u064A \u064A\u062A\u0631\u0627\u0648\u062D \u0628\u064A\u0646 100\u063A \u0648300\u063A \u0641\u064A \u0627\u0644\u062D\u0627\u0644\u0627\u062A \u0627\u0644\u062A\u0627\u0644\u064A\u0629:",list:["\u0639\u0646\u062F \u0627\u0644\u0633\u0641\u0631 \u0644\u0645\u0633\u0627\u0641\u0627\u062A \u0637\u0648\u064A\u0644\u0629 \u062F\u0648\u0646 \u062A\u0648\u0642\u0641.","\u0639\u0646\u062F \u0627\u0644\u062A\u0632\u0648\u062F \u0628\u062D\u0645\u0648\u0644\u0629 \u062B\u0642\u064A\u0644\u0629 \u0623\u0648 \u0632\u0627\u0626\u062F\u0629.","\u0639\u0646\u062F \u0627\u0644\u0633\u064A\u0631 \u0641\u064A \u0627\u0644\u0637\u0631\u064A\u0642 \u0627\u0644\u0633\u064A\u0627\u0631\u0629."],imageOrSvg:'<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><rect x="25" y="40" width="50" height="40" rx="5" fill="#0284c7"/><rect x="35" y="30" width="30" height="10" rx="2" fill="#0369a1"/><path d="M 50 10 L 50 25" stroke="#22c55e" stroke-width="5" marker-end="url(#arrow)"/><text x="50" y="65" font-size="8" fill="white" font-weight="bold" text-anchor="middle">+100g to +300g</text></svg>',alertType:"info"}]},{id:"ch8-sec2",title:"2. \u0633\u0648\u0627\u0626\u0644 \u0648\u0623\u062C\u0632\u0627\u0621 \u0627\u0644\u0645\u062D\u0631\u0643",icon:"fa-gears",type:"general",items:[{id:"ch8-r6",title:"\u0632\u064A\u062A \u0627\u0644\u0645\u062D\u0631\u0643",description:"\u0627\u0644\u0632\u064A\u062A \u0647\u0648 \u0634\u0631\u064A\u0627\u0646 \u062D\u064A\u0627\u0629 \u0627\u0644\u0645\u062D\u0631\u0643 \u0648\u064A\u062C\u0628 \u0645\u0631\u0627\u0642\u0628\u062A\u0647 \u0628\u0627\u0633\u062A\u0645\u0631\u0627\u0631:",list:["\u062F\u0648\u0631\u064A\u0629 \u0627\u0644\u062A\u063A\u064A\u064A\u0631: \u0643\u0644 10,000 \u0643\u0644\u0645 \u0643\u062D\u062F \u0623\u0642\u0635\u0649.","\u0627\u0644\u0645\u0633\u062A\u0648\u0649: \u064A\u062C\u0628 \u0623\u0646 \u064A\u0643\u0648\u0646 \u062F\u0627\u0626\u0645\u0627\u064B \u0628\u064A\u0646 \u0639\u0644\u0627\u0645\u062A\u064A Max \u0648 Min.","\u0642\u0627\u0639\u062F\u0629 \u0630\u0647\u0628\u064A\u0629: \u0625\u0630\u0627 \u0627\u0646\u062E\u0641\u0636 \u0627\u0644\u0645\u0633\u062A\u0648\u0649 \u062C\u062F\u0627\u064B\u060C \u064A\u062C\u0628 \u062A\u0648\u0642\u064A\u0641 \u0627\u0644\u0645\u062D\u0631\u0643 \u0641\u0648\u0631\u0627\u064B."],imageOrSvg:'<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><path d="M 20 70 L 80 70 L 85 40 L 40 40 L 35 25 L 20 25 Z" fill="#eab308"/><path d="M 85 40 L 95 30" stroke="#eab308" stroke-width="8" stroke-linecap="round"/><circle cx="30" cy="55" r="5" fill="white" opacity="0.5"/></svg>',alertType:"danger"},{id:"ch8-r7",title:"\u0627\u0644\u0645\u0635\u0627\u0641\u064A \u0648\u0634\u0645\u0639\u0627\u062A \u0627\u0644\u0627\u062D\u062A\u0631\u0627\u0642",description:"\u0642\u0637\u0639 \u0627\u0644\u063A\u064A\u0627\u0631 \u0627\u0644\u062A\u064A \u062A\u0624\u062B\u0631 \u0645\u0628\u0627\u0634\u0631\u0629 \u0639\u0644\u0649 \u0627\u0633\u062A\u0647\u0644\u0627\u0643 \u0627\u0644\u0648\u0642\u0648\u062F \u0648\u0642\u0648\u0629 \u0627\u0644\u0645\u062D\u0631\u0643:",list:["\u0645\u0635\u0641\u0627\u0629 \u0627\u0644\u0647\u0648\u0627\u0621: \u062A\u064F\u063A\u064A\u0631 \u0643\u0644 20,000 \u0643\u0644\u0645. \u0627\u062A\u0633\u0627\u062E\u0647\u0627 \u064A\u0632\u064A\u062F \u0627\u0644\u0627\u0633\u062A\u0647\u0644\u0627\u0643 \u0648\u064A\u062E\u0641\u0636 \u0627\u0644\u0642\u0648\u0629 (\u0644\u0643\u0646\u0647\u0627 \u0644\u0627 \u062A\u0644\u0648\u062B \u0627\u0644\u0633\u064A\u0627\u0631\u0629 \u0628\u062D\u062F \u0630\u0627\u062A\u0647\u0627).","\u0634\u0645\u0639\u0627\u062A \u0627\u0644\u0627\u062D\u062A\u0631\u0627\u0642 (Bougies): \u062A\u0622\u0643\u0644\u0647\u0627 \u064A\u0632\u064A\u062F \u0645\u0646 \u0627\u0633\u062A\u0647\u0644\u0627\u0643 \u0627\u0644\u0648\u0642\u0648\u062F \u0648\u064A\u0636\u0639\u0641 \u0642\u0648\u0629 \u0627\u0644\u0645\u062D\u0631\u0643.","\u0632\u064A\u062A \u0627\u0644\u0641\u0631\u0627\u0645\u0644: \u0625\u0630\u0627 \u0627\u0646\u062E\u0641\u0636 \u062A\u062D\u062A \u0627\u0644\u062D\u062F \u0627\u0644\u0623\u062F\u0646\u0649\u060C \u064A\u062C\u0628 \u0625\u0635\u0644\u0627\u062D \u0627\u0644\u062A\u0633\u0631\u0628 \u0641\u0648\u0631\u0627\u064B."],imageOrSvg:'<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><rect x="30" y="20" width="40" height="60" rx="5" fill="#475569"/><rect x="35" y="25" width="30" height="50" fill="#94a3b8" stroke-width="2" stroke-dasharray="2,2"/><path d="M 50 10 L 50 20" stroke="#ef4444" stroke-width="4"/></svg>',alertType:"warning"},{id:"ch8-r8",title:"\u0627\u0644\u0628\u0637\u0627\u0631\u064A\u0629 \u0648\u0633\u0648\u0627\u0626\u0644\u0647\u0627",description:"\u0635\u064A\u0627\u0646\u0629 \u0646\u0638\u0627\u0645 \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064A \u0648\u0627\u0644\u0637\u0627\u0642\u0629:",list:["\u0633\u0627\u0626\u0644 \u0627\u0644\u0628\u0637\u0627\u0631\u064A\u0629: \u064A\u062A\u0643\u0648\u0646 \u0645\u0646 \u062E\u0644\u064A\u0637 \u0645\u0627\u0621 \u0645\u0642\u0637\u0631 \u0648\u062D\u0627\u0645\u0636 \u0643\u0628\u0631\u064A\u062A\u064A.","\u062A\u0634\u062D\u064A\u0645 \u0627\u0644\u0623\u0637\u0631\u0627\u0641: \u064A\u062C\u0628 \u062F\u0647\u0646 \u0623\u0637\u0631\u0627\u0641 \u0627\u0644\u0628\u0637\u0627\u0631\u064A\u0629 \u0628\u0645\u0627\u062F\u0629 \u0639\u0627\u0632\u0644\u0629 \u0644\u0645\u0646\u0639 \u062A\u0633\u0631\u0628 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621.","\u062D\u0627\u0645\u0644 \u0627\u0644\u0623\u0645\u062A\u0639\u0629: \u064A\u0632\u064A\u062F \u0627\u0633\u062A\u0647\u0644\u0627\u0643 \u0627\u0644\u0648\u0642\u0648\u062F \u0628\u0634\u0643\u0644 \u0645\u0644\u062D\u0648\u0638 \u0648\u0644\u0648 \u0643\u0627\u0646 \u0641\u0627\u0631\u063A\u0627\u064B."],imageOrSvg:'<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><rect x="20" y="30" width="60" height="50" rx="3" fill="#1e293b"/><rect x="30" y="20" width="10" height="10" fill="#ef4444"/><rect x="60" y="20" width="10" height="10" fill="#94a3b8"/><text x="35" y="28" font-size="12" fill="#ef4444" font-weight="bold">+</text><text x="65" y="28" font-size="12" fill="#94a3b8" font-weight="bold">-</text></svg>'}]},{id:"ch8-sec3",title:"3. \u0627\u0644\u062A\u062D\u0643\u0645 \u0641\u064A \u0627\u0644\u0637\u0627\u0642\u0629 \u0648\u0627\u0644\u0628\u064A\u0626\u0629",icon:"fa-leaf",type:"general",items:[{id:"ch8-r11",title:"\u0623\u062F\u062E\u0646\u0629 \u0627\u0644\u0645\u062D\u0631\u0643 \u0648\u0627\u0644\u0623\u0639\u0637\u0627\u0644",description:"\u0643\u062B\u0627\u0641\u0629 \u0627\u0644\u062F\u062E\u0627\u0646 \u0627\u0644\u0645\u0646\u0628\u0639\u062B \u062A\u062F\u0644 \u0639\u0644\u0649 \u062E\u0644\u0644 \u062E\u0637\u064A\u0631 \u0641\u064A \u0627\u0644\u0645\u062D\u0631\u0643:",list:["\u0639\u0646\u062F \u0627\u0646\u0628\u0639\u0627\u062B \u062F\u062E\u0627\u0646 \u0643\u062B\u064A\u0641: \u064A\u062C\u0628 \u062A\u0648\u0642\u064A\u0641 \u0627\u0644\u0645\u062D\u0631\u0643 \u0641\u0648\u0631\u0627\u064B \u0648\u0627\u0644\u0627\u0646\u062A\u0638\u0627\u0631 \u062D\u062A\u0649 \u064A\u0628\u0631\u062F.","\u062F\u062E\u0627\u0646 \u0623\u0633\u0648\u062F: \u062E\u0644\u0644 \u0641\u064A \u0627\u062D\u062A\u0631\u0627\u0642 \u0627\u0644\u0648\u0642\u0648\u062F (\u0627\u062D\u062A\u0631\u0627\u0642 \u063A\u064A\u0631 \u0643\u0627\u0645\u0644).","\u062F\u062E\u0627\u0646 \u0623\u0632\u0631\u0642: \u0627\u062D\u062A\u0631\u0627\u0642 \u0632\u064A\u062A \u0627\u0644\u0645\u062D\u0631\u0643 \u062F\u0627\u062E\u0644 \u063A\u0631\u0641 \u0627\u0644\u0627\u062D\u062A\u0631\u0627\u0642.","\u062F\u062E\u0627\u0646 \u0623\u0628\u064A\u0636: \u062A\u0633\u0631\u0628 \u0633\u0627\u0626\u0644 \u0627\u0644\u062A\u0628\u0631\u064A\u062F \u0623\u0648 \u0648\u062C\u0648\u062F \u0645\u0627\u0621 \u0628\u0627\u0644\u0648\u0642\u0648\u062F."],imageOrSvg:'<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><path d="M 20 80 Q 40 60 60 80 Q 80 100 90 80" fill="none" stroke="#94a3b8" stroke-width="10" stroke-linecap="round" opacity="0.6"/><path d="M 30 70 Q 50 50 70 70" fill="none" stroke="#64748b" stroke-width="8" stroke-linecap="round" opacity="0.4"/></svg>',alertType:"danger"}]}]};export{t as a};
